import {seedState,uid,ROLES,STATUS,REQUEST_STATUS,formatMoney,formatDate,nowDate,clientOf,versionsOf,latestVersion,roundInfo,canReview,canUpload,canDeliver,canAcceptAgreement,canDecideExtra,visibility,requestVisibility,allowedFile} from './domain.mjs';
import {loadState,saveState,resetState,saveFile,readFile,resetFiles} from './store.mjs';

let data=loadState();
const params=new URLSearchParams(location.search);
const validRoles=Object.keys(ROLES);
const ui={view:'dashboard',role:validRoles.includes(params.get('role'))?params.get('role'):'freelancer',clientId:data.clients.some(c=>c.id===params.get('client'))?params.get('client'):'c1',projectId:null,tab:'overview',versionId:null,search:'',filter:'all',pinDraft:null,highlight:null,mobileNav:false,uploadUrl:null,modal:null};
const app=document.getElementById('app');
const root=document.getElementById('modal-root');
const toastRoot=document.getElementById('toast-root');
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeHTML;
const safeText=(value,fallback='—')=>value?e(value):fallback;
const svgPath={
  dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
  projects:'<rect x="3" y="7" width="18" height="13" rx="2"/><path d="M3 7V5a2 2 0 0 1 2-2h5l2 4"/>',
  requests:'<path d="M5 4h14v16H5z"/><path d="M8 9h8M8 13h8M8 17h5"/>',
  agreements:'<path d="M7 2h9l5 5v15H7a3 3 0 0 1-3-3V5a3 3 0 0 1 3-3Z"/><path d="M16 2v6h5M9 12h8M9 16h8"/>',
  reviews:'<path d="M4 5h16v12H8l-4 4z"/><path d="M8 10h8M8 14h5"/>',
  deliveries:'<rect x="4" y="5" width="16" height="15" rx="2"/><path d="M4 10h16M9 3v4M15 3v4M9 15l2 2 4-4"/>',
  finance:'<rect x="2" y="5" width="20" height="14" rx="3"/><path d="M2 10h20M16 15h2"/>',
  team:'<circle cx="9" cy="8" r="3"/><path d="M2 20v-2a5 5 0 0 1 5-5h4a5 5 0 0 1 5 5v2M17 5a3 3 0 0 1 0 6M19 14a5 5 0 0 1 3 5v1"/>',
  history:'<path d="M3 12a9 9 0 1 0 4-7M3 3v6h6"/><path d="M12 7v5l3 2"/>',
  plus:'<path d="M12 5v14M5 12h14"/>',chevron:'<path d="m9 18 6-6-6-6"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',
  menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="M5 5l14 14M19 5 5 19"/>',check:'<path d="m5 12 4 4L19 6"/>',edit:'<path d="m5 17 12-12 3 3-12 12H5z"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M5 21h14"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 17v4h16v-4"/>',reset:'<path d="M3 12a9 9 0 1 0 4-7M3 3v6h6"/>',file:'<path d="M6 3h8l5 5v13H6zM14 3v5h5"/>',warning:'<path d="m12 2 10 18H2zM12 8v5m0 4v.1"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',spark:'<path d="m12 3 2 7 7 2-7 2-2 7-2-7-7-2 7-2z"/>',paperclip:'<path d="m9 13 5-5a3 3 0 0 1 4 4l-8 8a5 5 0 0 1-7-7l9-9"/>',lock:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',share:'<circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m9 11 6-5m-6 8 6 4"/>'
};
const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${svgPath[name]||svgPath.file}</svg>`;
const btn=(label,action,cls='btn-white',attrs='')=>`<button class="btn ${cls}" type="button" data-action="${action}" ${attrs}>${label}</button>`;
const status=p=>{const x=STATUS[p?.status]||{label:p?.status??'Desconocido',tone:'grey'};return `<span class="pill ${x.tone}">${e(x.label)}</span>`;};
const userName=()=>ui.role==='client'?data.clients.find(c=>c.id===ui.clientId)?.contact||'Cliente':ui.role==='agency'?'Equipo creativo':'Alex Moreno';
const actor=()=>userName();
const currentProjects=()=>visibility(data,ui.role,ui.clientId);
const projectById=id=>currentProjects().find(p=>p.id===id)||null;
const allProjectById=id=>data.projects.find(p=>p.id===id)||null;
const ownerOf=p=>data.team.find(t=>t.id===p.ownerId);
const clientBadge=c=>`<span class="project-icon" style="background:${e(c?.color||'#e9eaf2')}">${e(c?.initials||'PR')}</span>`;
const eventIcon=k=>icon(k==='approval'||k==='delivery'?'check':k==='comment'?'reviews':k==='agreement'?'agreements':k==='request'?'requests':'history',15);
function navs(){return [{id:'dashboard',label:'Inicio',icon:'dashboard'},{id:'projects',label:'Proyectos',icon:'projects'},{id:'requests',label:'Solicitudes',icon:'requests'},{id:'agreements',label:'Acuerdos',icon:'agreements'},{id:'reviews',label:'Revisiones',icon:'reviews'},{id:'deliveries',label:'Entregas',icon:'deliveries'},...(ui.role!=='client'?[{id:'finance',label:'Presupuestos',icon:'finance'}]:[{id:'finance',label:'Extras de alcance',icon:'finance'}]),...(ui.role==='agency'?[{id:'team',label:'Equipo',icon:'team'}]:[]),{id:'history',label:'Actividad',icon:'history'}];}
function titleForView(){return ({dashboard:'Resumen general',projects:'Proyectos',requests:'Solicitudes',agreements:'Acuerdos',reviews:'Revisiones',deliveries:'Entregas',finance:'Presupuestos y alcance',team:'Equipo creativo',history:'Actividad',detail:'Detalle del proyecto'})[ui.view]||'TrazoDesk';}
function eventRecord(projectId,text,kind='history'){data.events.unshift({id:uid('e'),projectId,text,actor:actor(),createdAt:new Date().toISOString(),kind});}
function persist(){if(!saveState(data))toast('Cambios en memoria: el navegador bloqueó el almacenamiento local.','error');}
function toast(text,type='info'){const d=document.createElement('div');d.className=`toast ${type}`;d.textContent=text;toastRoot.className='toasts';toastRoot.append(d);setTimeout(()=>d.remove(),4500);}
function viewTo(view){ui.view=view;ui.projectId=null;ui.tab='overview';ui.versionId=null;ui.search='';ui.filter='all';ui.mobileNav=false;ui.pinDraft=null;render();window.scrollTo({top:0,behavior:'instant'});}
function openProject(id,tab='overview'){const p=projectById(id);if(!p){toast('Ese proyecto no está disponible en esta perspectiva.','error');return;} ui.view='detail';ui.projectId=id;ui.tab=tab;ui.versionId=latestVersion(data,id)?.id||null;ui.pinDraft=null;ui.highlight=null;ui.mobileNav=false;render();window.scrollTo({top:0,behavior:'instant'});}
const blank=(title,desc,action='')=>`<div class="empty"><div class="empty-icon">${icon('file',26)}</div><strong>${e(title)}</strong><p>${e(desc)}</p>${action}</div>`;
const pageHead=(kicker,title,subtitle,actions='')=>`<div class="page-header"><div><div class="eyebrow">${e(kicker)}</div><h1>${e(title)}</h1><p>${e(subtitle)}</p></div>${actions?`<div class="page-actions">${actions}</div>`:''}</div>`;
function render(){
  if(ui.view==='detail'&&!projectById(ui.projectId)){ui.view='dashboard';ui.projectId=null;clearPreview();}
  const navitems=navs();if(!navitems.some(v=>v.id===ui.view)&&ui.view!=='detail')ui.view='dashboard';
  app.innerHTML=`<div class="layout ${ui.mobileNav?'sidebar-open':''}">
    ${ui.mobileNav?'<div class="mobile-overlay" data-action="mobile-close"></div>':''}
    <aside class="sidebar"><div class="brand"><div class="brand-symbol">T.</div><div><div class="brand-name">TrazoDesk</div><small>Creative workflow</small></div></div>
      <div class="nav-label">Espacio de trabajo</div><nav aria-label="Navegación principal">${navitems.map(n=>`<button type="button" data-nav="${n.id}" class="nav-item ${ui.view===n.id||(ui.view==='detail'&&n.id==='projects')?'active':''}">${icon(n.icon,18)} ${e(n.label)}${n.id==='requests'&&requestVisibility(data,ui.role,ui.clientId).some(r=>r.status==='pending')?'<em>'+requestVisibility(data,ui.role,ui.clientId).filter(r=>r.status==='pending').length+'</em>':''}</button>`).join('')}</nav>
      <div class="sidebar-bottom"><div class="tip"><strong>${icon('spark',14)} Modo demostración</strong>Datos ficticios y cambios locales. No hay usuarios, pagos ni enlaces privados reales.</div><button class="nav-item" type="button" data-action="reset">${icon('reset',17)} Reiniciar demo</button></div>
    </aside>
    <main class="main"><header class="topbar"><div class="top-left"><button class="icon-btn mobile-toggle" data-action="mobile-open" aria-label="Abrir menú">${icon('menu')}</button><span class="top-title">${e(titleForView())}</span></div><div class="top-actions">
      ${ui.role==='client'?`<select id="client-switch" class="client-selector" aria-label="Seleccionar cliente de prueba">${data.clients.map(c=>`<option value="${e(c.id)}" ${c.id===ui.clientId?'selected':''}>${e(c.name)}</option>`).join('')}</select>`:''}
      <div class="mode-wrap"><span class="switcher-hint">Vista</span><select id="role-switch" aria-label="Cambiar perspectiva">${Object.entries(ROLES).map(([key,value])=>`<option value="${key}" ${ui.role===key?'selected':''}>${e(value.label)}</option>`).join('')}</select></div>
      <button class="icon-btn" data-nav="history" aria-label="Abrir actividad" title="Actividad">${icon('bell')}</button><div class="avatar user-avatar" title="${e(userName())}">${e(userName().split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase())}</div></div></header>
      <div class="content"><div class="demo-banner">${icon('warning',17)} <span><strong>Demo interactiva, no SaaS activo.</strong> Roles simulados sin autenticación. Todo se guarda en este navegador; no compartas información real.</span></div>${renderView()}</div>
    </main></div>`;
}
function renderView(){switch(ui.view){case 'dashboard':return dashboard();case 'projects':return projectsPage();case 'requests':return requestsPage();case 'agreements':return agreementsPage();case 'reviews':return reviewsPage();case 'deliveries':return deliveriesPage();case 'finance':return financePage();case 'team':return teamPage();case 'history':return historyPage();case 'detail':return projectDetail();default:return dashboard();}}
function projectRow(p){const c=clientOf(data,p);return `<div class="project-row">${clientBadge(c)}<div class="project-row-main"><strong>${e(p.name)}</strong><span>${e(c?.name||'Cliente')} · Fecha objetivo: ${formatDate(p.deadline)}</span></div><div class="project-actions">${status(p)} <button class="icon-btn" title="Abrir proyecto" aria-label="Abrir ${e(p.name)}" data-open-project="${e(p.id)}">${icon('chevron',17)}</button></div></div>`;}
function activityRows(events,limit=7){return events.slice(0,limit).map(ev=>{const p=allProjectById(ev.projectId);return `<div class="activity-row"><span class="activity-dot">${eventIcon(ev.kind)}</span><div class="activity-info"><strong>${e(ev.text)}</strong><span>${e(ev.actor)} · ${formatDate(ev.createdAt)}${p?` · ${e(p.name)}`:''}</span></div>${p&&projectById(p.id)?`<button class="icon-btn" aria-label="Ir a proyecto" data-open-project="${e(p.id)}">${icon('chevron',16)}</button>`:''}</div>`;}).join('');}
function visibleEvents(){const ids=new Set(currentProjects().map(p=>p.id));return data.events.filter(x=>!x.projectId||ids.has(x.projectId)).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));}
function dashboard(){const ps=currentProjects(),pending=ps.filter(p=>p.status==='in_review').length,active=ps.filter(p=>['active','changes_requested','in_review'].includes(p.status)).length,delivered=ps.filter(p=>p.status==='delivered').length;const requests=requestVisibility(data,ui.role,ui.clientId).filter(r=>r.status==='pending').length;
 return `${pageHead('Panel de trabajo',`Hola, ${userName().split(' ')[0]}`,'Tu trabajo creativo, organizado desde el acuerdo hasta la entrega.',ui.role==='client'?btn(icon('plus')+' Nueva solicitud','new-request','btn-primary'):btn(icon('plus')+' Nuevo proyecto','new-project','btn-primary'))}
 <section class="hero mb"><div class="hero-copy"><span class="hero-kicker">TrazoDesk · Demo</span><h2>${ui.role==='client'?'Revisa, comenta y aprueba con claridad.':ui.role==='agency'?'Tu estudio, todos los proyectos bajo control.':'Menos correos. Más claridad creativa.'}</h2><p>Centraliza solicitudes, acuerdos, versiones, anotaciones, cambios y entregas desde un solo flujo.</p>${btn(ui.role==='client'?'Ver revisiones '+icon('arrow',14):'Explorar proyectos '+icon('arrow',14),ui.role==='client'?'goto-reviews':'goto-projects','btn-white')}</div><div class="hero-stat"><div class="hero-disc">${ps.length}<small>proyectos</small></div></div></section>
 <div class="grid grid-4 mb">${statCard('Proyectos totales',ps.length,'En tu perspectiva','projects','purple')}${statCard('En proceso',active,'En curso y revisiones','reviews','blue')}${statCard('Por revisar',pending,'Esperando aprobación','agreements','orange')}${statCard('Entregados',delivered,'Finalizados','deliveries','green')}</div>
 <div class="grid grid-3"><section class="card card-pad span-2"><div class="section-head"><div><h2 class="section-title">Proyectos recientes</h2><p class="card-subtitle">Estado actualizado de los entregables</p></div><button class="linkish" data-nav="projects">Ver todos ${icon('arrow',13)}</button></div>${ps.length?ps.slice(0,4).map(projectRow).join(''):blank('No hay proyectos','Selecciona otra cuenta de cliente o crea una solicitud.')}</section>
 <section class="card card-pad"><div class="section-head"><div><h2 class="section-title">Tu siguiente paso</h2><p class="card-subtitle">Acciones recomendadas de la demo</p></div></div><div class="stack">${actionTeasers(ps,requests)}</div></section></div>
 <div class="grid grid-3 mt"><section class="card card-pad span-2"><div class="section-head"><div><h2 class="section-title">Actividad reciente</h2><p class="card-subtitle">Historial demostrativo y acciones locales</p></div><button class="linkish" data-nav="history">Historial completo</button></div>${visibleEvents().length?activityRows(visibleEvents(),5):blank('Sin actividad','Aquí aparecerán tus movimientos.')}</section>
 <section class="card card-pad"><div class="section-head"><div><h2 class="section-title">Cómo funciona</h2><p class="card-subtitle">El proceso de punta a punta</p></div></div><div class="stack">${[['1','Solicitud y acuerdo'],['2','Producción y versiones'],['3','Revisión y anotaciones'],['4','Aprobación y entrega']].map(x=>`<div class="mini-pretty"><span class="strong">${x[0]}. ${x[1]}</span>${icon('check',15)}</div>`).join('')}</div></section></div>`;}
function statCard(label,count,note,ico,color){return `<div class="card stat"><div class="stat-line"><span class="stat-label">${e(label)}</span><span class="stat-icon ${color}">${icon(ico,21)}</span></div><strong class="mono">${count}</strong><span class="stat-foot">${e(note)}</span></div>`;}
function actionTeasers(ps,requests){const pendingAgreement=ps.find(p=>p.status==='agreement');const toReview=ps.find(p=>p.status==='in_review');const approved=ps.find(p=>p.status==='approved');let items=[];
 if(ui.role==='client'){if(toReview)items.push(`<div class="mini-pretty"><div><div class="strong">Revisar entrega</div><span class="caption">${e(toReview.name)}</span></div><button class="icon-btn" data-open-project="${e(toReview.id)}" data-open-tab="review">${icon('arrow')}</button></div>`);if(pendingAgreement)items.push(`<div class="mini-pretty"><div><div class="strong">Aceptar acuerdo</div><span class="caption">${e(pendingAgreement.name)}</span></div><button class="icon-btn" data-open-project="${e(pendingAgreement.id)}" data-open-tab="agreement">${icon('arrow')}</button></div>`);}else{if(approved)items.push(`<div class="mini-pretty"><div><div class="strong">Preparar entrega</div><span class="caption">${e(approved.name)}</span></div><button class="icon-btn" data-open-project="${e(approved.id)}" data-open-tab="delivery">${icon('arrow')}</button></div>`);if(pendingAgreement)items.push(`<div class="mini-pretty"><div><div class="strong">Acuerdo pendiente</div><span class="caption">${e(pendingAgreement.name)}</span></div><button class="icon-btn" data-open-project="${e(pendingAgreement.id)}" data-open-tab="agreement">${icon('arrow')}</button></div>`);}
 if(requests)items.push(`<div class="mini-pretty"><div><div class="strong">${requests} solicitudes pendientes</div><span class="caption">Revisar nuevas propuestas</span></div><button class="icon-btn" data-nav="requests">${icon('arrow')}</button></div>`);
 if(!items.length)items.push(`<div class="note success">No hay acciones urgentes en esta cuenta de ejemplo.</div>`);
 return items.join('')+`<div class="note">Cambia la perspectiva en la parte superior para probar Freelancer, Agencia y Cliente. Los datos son los mismos, pero cambian los permisos.</div>`;}
function projectsPage(){let ps=currentProjects();if(ui.filter!=='all')ps=ps.filter(p=>p.status===ui.filter);if(ui.search)ps=ps.filter(p=>(p.name+' '+clientOf(data,p)?.name+' '+p.service).toLowerCase().includes(ui.search.toLowerCase()));return `${pageHead('Portafolio de trabajo','Proyectos','Todos los proyectos visibles para la perspectiva seleccionada.',ui.role==='client'?'':btn(icon('plus')+' Crear proyecto','new-project','btn-primary'))}<div class="toolbar"><div class="tabs">${[['all','Todos'],['agreement','Acuerdos'],['active','En producción'],['in_review','En revisión'],['changes_requested','Con cambios'],['approved','Aprobados'],['delivered','Entregados']].map(([id,label])=>`<button class="tab ${ui.filter===id?'active':''}" data-filter="${id}">${label}</button>`).join('')}</div><input id="project-search" class="search" placeholder="Buscar proyectos…" aria-label="Buscar proyectos" value="${e(ui.search)}"></div><div class="grid grid-3">${ps.map(p=>{const c=clientOf(data,p);const owner=ownerOf(p);return `<article class="card project-tile"><div class="tile-top">${clientBadge(c)}${status(p)}</div><div><h2 class="tile-name">${e(p.name)}</h2><div class="tile-desc">${e(c?.name||'Cliente')} · ${e(p.service)}</div></div><div class="mini-metrics"><span>${icon('history',13)} ${formatDate(p.deadline)}</span><span>${icon('file',13)} ${versionsOf(data,p.id).length} versiones</span></div><div class="tile-footer"><div class="action-row"><span class="small-avatar" style="background:${e(owner?.tone||'#eef0f6')}">${e(owner?.initials||'—')}</span><span class="caption dots">${e(owner?.name||'Sin asignar')}</span></div><button class="btn btn-soft btn-sm" data-open-project="${p.id}">Abrir ${icon('arrow',13)}</button></div></article>`;}).join('')}</div>${!ps.length?blank('Sin resultados','Prueba otro filtro o búsqueda.'):''}`;}
function requestsPage(){const rs=requestVisibility(data,ui.role,ui.clientId).filter(r=>ui.filter==='all'||r.status===ui.filter);return `${pageHead('Entrada de trabajo','Solicitudes','Convierte un encargo en un proyecto con alcance y acuerdo verificables.',btn(icon('plus')+' Nueva solicitud','new-request','btn-primary'))}<div class="toolbar"><div class="tabs">${[['all','Todas'],['pending','Pendientes'],['accepted','Convertidas'],['rejected','Descartadas']].map(([id,label])=>`<button class="tab ${ui.filter===id?'active':''}" data-filter="${id}">${label}</button>`).join('')}</div></div><section class="card card-pad">${rs.length?rs.map(r=>{const c=data.clients.find(c=>c.id===r.clientId);return `<div class="request-row">${clientBadge(c)}<div class="project-row-main"><strong>${e(r.title)}</strong><span>${e(c?.name||'Cliente')} · ${e(r.service)} · ${formatDate(r.deadline)}</span><span style="white-space:normal;margin-top:7px">${e(r.details)}</span><div class="action-row" style="margin-top:9px"><span class="pill ${r.status==='pending'?'amber':r.status==='accepted'?'green':'grey'}">${e(REQUEST_STATUS[r.status]||r.status)}</span><b class="caption">Presupuesto referencial: ${formatMoney(r.budget)}</b></div></div>${ui.role!=='client'&&r.status==='pending'?`<div class="action-row">${btn('Convertir','accept-request','btn-primary btn-sm',`data-id="${r.id}"`)}${btn('Descartar','reject-request','btn-white btn-sm',`data-id="${r.id}"`)}</div>`:''}</div>`;}).join(''):blank('No hay solicitudes','Crea una nueva solicitud o cambia los filtros.')}</section><div class="note mt">Una solicitud aceptada crea un proyecto con acuerdo pendiente; no equivale a una aceptación automática del presupuesto por parte del cliente.</div>`;}
function agreementsPage(){const ps=currentProjects();return `${pageHead('Acuerdos de trabajo','Acuerdos y alcance','Condiciones documentadas antes de comenzar la producción.')}<div class="grid grid-2">${ps.map(p=>`<article class="card card-pad"><div class="section-head"><div><div class="eyebrow">${e(clientOf(data,p)?.name)}</div><h2 class="card-title">${e(p.name)}</h2></div>${p.agreementAcceptedAt?'<span class="pill green">Aceptado</span>':'<span class="pill amber">Pendiente</span>'}</div><dl><div class="kv"><dt>Servicio</dt><dd>${e(p.service)}</dd></div><div class="kv"><dt>Importe acordado</dt><dd>${formatMoney(p.budget)}</dd></div><div class="kv"><dt>Rondas incluidas</dt><dd>${p.rounds}</dd></div><div class="kv"><dt>Fecha objetivo</dt><dd>${formatDate(p.deadline)}</dd></div></dl><p class="helper">${e(p.scope)}</p><div class="action-row">${btn('Ver acuerdo '+icon('arrow',14),'view-agreement','btn-soft btn-sm',`data-id="${e(p.id)}"`)}</div></article>`).join('')}</div>${!ps.length?blank('No hay acuerdos','No existen proyectos visibles.'):''}`;}
function reviewsPage(){const ps=currentProjects().filter(p=>versionsOf(data,p.id).length);return `${pageHead('Feedback visual','Revisiones y versiones','Comentarios situados sobre los entregables, decisiones y rondas de cambios.')}<div class="grid grid-3">${ps.map(p=>{const v=latestVersion(data,p.id),round=roundInfo(data,p.id),pending=data.comments.filter(c=>c.versionId===v.id&&!c.resolved).length;return `<article class="card project-tile"><div class="tile-top">${clientBadge(clientOf(data,p))}${status(p)}</div><h2 class="tile-name">${e(p.name)}</h2><p class="caption">Versión ${v.number} · ${e(v.label)}</p><div class="mini-metrics"><span>${icon('reviews',14)} ${pending} comentarios abiertos</span><span>Rondas solicitadas ${round.used}/${round.included}</span></div><div class="tile-footer"><span class="caption">${formatDate(v.createdAt)}</span><button class="btn btn-soft btn-sm" data-open-project="${p.id}" data-open-tab="review">Revisar ${icon('arrow',13)}</button></div></article>`;}).join('')}</div>${!ps.length?blank('Sin entregables','Los nuevos archivos aparecerán aquí cuando se cargue su primera versión.'):''}`;}
function deliveriesPage(){const ps=currentProjects().filter(p=>['approved','delivered'].includes(p.status));return `${pageHead('Cierre del proceso','Entregas','Archivos aprobados y registro de entrega final.')}<div class="grid grid-2">${ps.map(p=>{const v=latestVersion(data,p.id);return `<section class="card card-pad"><div class="section-head"><div><div class="eyebrow">${e(clientOf(data,p)?.name)}</div><h2 class="card-title">${e(p.name)}</h2></div>${status(p)}</div><div class="mini-pretty"><div class="doc-icon">${icon('file',20)}</div><div style="flex:1;min-width:0"><div class="file-label">${e(v?.filename||'Sin archivo')}</div><div class="caption">Versión aprobada ${v?.number||'—'} · ${formatDate(v?.createdAt)}</div></div></div><div class="action-row mt">${p.status==='approved'&&ui.role!=='client'?btn(icon('check')+' Registrar entrega','deliver','btn-primary',`data-id="${p.id}"`):p.status==='approved'?'<span class="helper">Esperando que el creativo registre la entrega.</span>':btn(icon('download')+' Descargar archivo final','download','btn-primary',`data-id="${e(v?.id||'')}"`)}${btn('Ver detalle','view-delivery','btn-white',`data-id="${p.id}"`)}</div></section>`;}).join('')}</div>${!ps.length?blank('Aún no hay entregas','Cuando un cliente apruebe un archivo, aparecerá aquí.'):''}<div class="note mt">La descarga funciona con archivos de ejemplo o archivos guardados localmente en este navegador. No se comparten entre equipos ni usuarios reales.</div>`;}
function financePage(){const ps=currentProjects();const ids=new Set(ps.map(p=>p.id));const extras=data.extras.filter(x=>ids.has(x.projectId));const budget=ps.reduce((s,p)=>s+(Number(p.budget)||0),0);const approvedExtras=extras.filter(x=>x.status==='accepted').reduce((s,x)=>s+(Number(x.amount)||0),0);
 return `${pageHead('Control de alcance','Presupuestos y cambios extra','Seguimiento ilustrativo de importes acordados y cambios fuera de alcance.',ui.role==='client'?'':btn(icon('plus')+' Proponer extra','new-extra','btn-primary'))}<div class="note warn mb"><strong>Sin pagos ni facturación.</strong> Los importes son ejemplos para validar acuerdos y ampliaciones de alcance. No se cobra, factura ni transfiere dinero.</div><div class="grid grid-3 mb">${statCard('Importe de proyectos',formatMoney(budget),'Referencial; no cobrado','finance','purple')}${statCard('Extras aceptados',formatMoney(approvedExtras),'Acuerdos de ampliación','check','green')}${statCard('Extras pendientes',extras.filter(x=>x.status==='pending').length,'Por aprobar o rechazar','history','orange')}</div><section class="card card-pad"><div class="section-head"><h2 class="section-title">Registro de cambios extra</h2></div>${extras.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Proyecto</th><th>Concepto</th><th>Importe</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${extras.map(x=>{const p=allProjectById(x.projectId);return `<tr><td>${e(p?.name)}</td><td>${e(x.title)}</td><td class="money">${formatMoney(x.amount)}</td><td><span class="pill ${x.status==='accepted'?'green':x.status==='rejected'?'grey':'amber'}">${e(x.status==='accepted'?'Aceptado':x.status==='rejected'?'Rechazado':'Pendiente')}</span></td><td>${canDecideExtra(x,ui.role)?`<div class="action-row">${btn('Aceptar','accept-extra','btn-soft btn-sm',`data-id="${x.id}"`)}${btn('Rechazar','reject-extra','btn-white btn-sm',`data-id="${x.id}"`)}</div>`:'<span class="caption">—</span>'}</td></tr>`;}).join('')}</tbody></table></div>`:blank('Sin extras','No se registraron cambios adicionales para estos proyectos.')}</section>`;}
function teamPage(){if(ui.role!=='agency')return blank('Acceso no disponible','Cambia a Agencia para ver este módulo.');return `${pageHead('Estudio creativo','Equipo y asignaciones','Vista de coordinación interna, sin cuentas ni permisos de servidor.')}<div class="grid grid-3">${data.team.map(m=>{const ps=data.projects.filter(p=>p.ownerId===m.id);return `<article class="card agency-card"><span class="avatar" style="width:54px;height:54px;background:${e(m.tone)}">${e(m.initials)}</span><div><strong>${e(m.name)}</strong><small>${e(m.role)}</small><div class="mini-metrics mt"><span>${ps.length} proyectos asignados</span></div></div></article>`;}).join('')}</div><section class="card card-pad mt"><div class="section-head"><h2 class="section-title">Distribución de proyectos</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Proyecto</th><th>Estado</th><th>Responsable</th><th>Acciones</th></tr></thead><tbody>${data.projects.map(p=>`<tr><td><strong>${e(p.name)}</strong></td><td>${status(p)}</td><td>${e(ownerOf(p)?.name||'Sin asignar')}</td><td>${btn('Reasignar','assign','btn-soft btn-sm',`data-id="${p.id}"`)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function historyPage(){return `${pageHead('Trazabilidad','Historial de actividad','Acciones registradas dentro de esta demostración, por proyecto y perspectiva.')}
 <section class="card card-pad"><div class="section-head"><h2 class="section-title">Movimientos recientes</h2><button class="btn btn-white btn-sm" data-action="export-json">${icon('download',15)} Exportar datos demo</button></div>${visibleEvents().length?activityRows(visibleEvents(),100):blank('Sin actividad','Los eventos aparecerán al operar la demo.')}</section>`;}
function projectDetail(){const p=projectById(ui.projectId), c=clientOf(data,p), v=latestVersion(data,p.id),round=roundInfo(data,p.id),owner=ownerOf(p);
 const tabs=[['overview','Resumen'],['agreement','Acuerdo'],['review','Revisiones'],['delivery','Entrega'],['activity','Historial']];
 return `<div class="breadcrumb"><button data-nav="projects">Proyectos</button>${icon('chevron',12)}<span>${e(p.name)}</span></div><div class="detail-cover"><div><div class="eyebrow">${e(c?.name||'Cliente')} · ${e(p.service)}</div><h1>${e(p.name)}</h1><div class="mini-metrics"><span>${status(p)}</span><span>${icon('history',14)} ${formatDate(p.deadline)}</span><span>${icon('file',14)} ${versionsOf(data,p.id).length} versiones</span></div></div><div class="action-row">${ui.role!=='client'&&canUpload(p,ui.role)?btn(icon('upload')+' Subir versión','upload-version','btn-primary'):''}${ui.role!=='client'?btn(icon('share')+' Vista de cliente','copy-client-demo-link','btn-white'):''}${btn(icon('download')+' Descargar acuerdo','download-agreement','btn-white')}</div></div>
 <div class="detail-tabs" role="tablist" aria-label="Secciones del proyecto">${tabs.map(([id,label])=>`<button class="tab ${ui.tab===id?'active':''}" data-tab="${id}" role="tab" aria-selected="${ui.tab===id}">${label}</button>`).join('')}</div>
 ${ui.tab==='overview'?`<div class="grid grid-3"><section class="card card-pad span-2"><div class="section-head"><div><h2 class="section-title">Resumen del proyecto</h2><p class="card-subtitle">Del acuerdo a la entrega final</p></div></div><div class="steps mb">${[['agreement','Acuerdo'],['active','Producción'],['in_review','Revisión'],['delivered','Entrega']].map(([s,label],i)=>{const currentIdx=({agreement:0,active:1,changes_requested:2,in_review:2,approved:3,delivered:4})[p.status]??0;return `<div class="step ${currentIdx>i?'done':currentIdx===i?'current':''}"><strong>0${i+1} · ${label}</strong><small>${currentIdx>i?'Completado':currentIdx===i?'Etapa actual':'Pendiente'}</small></div>`;}).join('')}</div><h3 class="card-title">Alcance acordado</h3><p>${e(p.scope)}</p><h3 class="card-title" style="margin-top:16px">Fuera de alcance</h3><p class="muted">${e(p.exclusions||'No detallado')}</p><div class="action-row mt">${btn('Ver acuerdo '+icon('arrow',14),'tab-agreement','btn-soft')}${btn('Ir a revisiones '+icon('arrow',14),'tab-review','btn-white')}</div></section><aside class="card card-pad"><h2 class="section-title">Ficha rápida</h2><dl><div class="kv"><dt>Cliente</dt><dd>${e(c?.name)}</dd></div><div class="kv"><dt>Responsable</dt><dd>${e(owner?.name||'Sin asignar')}</dd></div><div class="kv"><dt>Presupuesto</dt><dd>${formatMoney(p.budget)}</dd></div><div class="kv"><dt>Rondas incluidas</dt><dd>${p.rounds}</dd></div><div class="kv"><dt>Cambios pedidos</dt><dd>${round.used} de ${round.included}</dd></div><div class="kv"><dt>Acuerdo</dt><dd>${p.agreementAcceptedAt?'Aceptado':'Pendiente'}</dd></div></dl></aside></div>`:''}
 ${ui.tab==='agreement'?agreementDetail(p):''}
 ${ui.tab==='review'?reviewDetail(p):''}
 ${ui.tab==='delivery'?deliveryDetail(p):''}
 ${ui.tab==='activity'?`<section class="card card-pad"><h2 class="section-title">Movimientos de este proyecto</h2>${activityRows(visibleEvents().filter(x=>x.projectId===p.id),100)||blank('Sin historial','Todavía no se registran movimientos.')}</section>`:''}`;}
function agreementDetail(p){const c=clientOf(data,p),round=roundInfo(data,p.id),extra=data.extras.filter(x=>x.projectId===p.id);return `<div class="grid grid-3"><section class="card card-pad span-2"><div class="section-head"><div><h2 class="section-title">Acuerdo de alcance</h2><p class="card-subtitle">Condiciones de este encargo de demostración</p></div>${p.agreementAcceptedAt?'<span class="pill green">Aceptado</span>':'<span class="pill amber">Por aceptar</span>'}</div><h3 class="card-title">Incluido</h3><p>${e(p.scope)}</p><hr class="short-hr"><h3 class="card-title">No incluido</h3><p class="muted">${e(p.exclusions||'No especificado')}</p><hr class="short-hr"><dl><div class="kv"><dt>Presupuesto</dt><dd>${formatMoney(p.budget)}</dd></div><div class="kv"><dt>Rondas incluidas</dt><dd>${p.rounds}</dd></div><div class="kv"><dt>Fecha objetivo</dt><dd>${formatDate(p.deadline)}</dd></div><div class="kv"><dt>Aceptación demo</dt><dd>${formatDate(p.agreementAcceptedAt)}</dd></div></dl>${canAcceptAgreement(p,ui.role)?`<div class="action-row mt">${btn(icon('check')+' Aceptar alcance y presupuesto','accept-agreement','btn-primary')}</div>`:''}${!p.agreementAcceptedAt?'<div class="note warn mt">La producción no podrá avanzar hasta aceptar el acuerdo desde la perspectiva Cliente correspondiente.</div>':'<div class="note success mt">Alcance aceptado. Las rondas y ampliaciones se registran de manera independiente.</div>'}</section><aside class="card card-pad"><h2 class="section-title">Rondas y extras</h2><div class="mini-metrics mb"><span class="numeric">${round.used}/${round.included}</span><span>rondas solicitadas</span></div><p class="caption">Una ronda se contabiliza cuando el cliente solicita cambios sobre una versión.</p>${round.overLimit?'<div class="note warn">Se alcanzó el número de rondas incluidas. Cualquier ampliación requiere un nuevo acuerdo de alcance; no se cobra automáticamente.</div>':''}<hr class="short-hr"><h3 class="card-title">Cambios fuera de alcance</h3>${extra.length?extra.map(x=>`<div class="mini-pretty" style="margin-top:10px"><div><strong>${e(x.title)}</strong><div class="caption">${formatMoney(x.amount)} · ${e(x.status==='accepted'?'Aceptado':x.status==='rejected'?'Rechazado':'Pendiente')}</div></div></div>`).join(''):'<p class="caption">Sin ampliaciones registradas.</p>'}${ui.role!=='client'?`<div class="mt">${btn(icon('plus')+' Proponer extra','new-extra','btn-soft')}</div>`:''}</aside></div>`;}
function decisionLabel(v){return v.decision==='approved'?'Aprobada':v.decision==='changes_requested'?'Cambios solicitados':v.decision==='superseded'?'Reemplazada':'Pendiente';}
let previewUrl=null;
function reviewDetail(p){const versions=versionsOf(data,p.id);if(!versions.length)return `<section class="card card-pad">${blank('Sin versiones','Desde la perspectiva Freelancer o Agencia, carga una imagen JPG/PNG o PDF para iniciar la revisión.',canUpload(p,ui.role)?btn(icon('upload')+' Subir primera versión','upload-version','btn-primary'):'')}</section>`;
 const v=versions.find(x=>x.id===ui.versionId)||versions[0];ui.versionId=v.id;
 const comments=data.comments.filter(x=>x.versionId===v.id).sort((a,b)=>new Date(a.createdAt)-new Date(b.createdAt));const latest=versions[0];const isPdf=v.kind==='application/pdf';const isAnnotatable=!isPdf;
 const canDecide=canReview(p,v,ui.role)&&v.id===latest.id;
 const isSample=!!v.sample;
 const stageSource=isSample?v.sample:(previewUrl||'');
 return `<div class="grid grid-3 mb"><div class="card card-pad"><span class="stat-label">Versión seleccionada</span><div class="numeric">V${v.number}</div><div class="caption">${e(decisionLabel(v))} · ${formatDate(v.createdAt)}</div></div><div class="card card-pad"><span class="stat-label">Rondas solicitadas</span><div class="numeric">${roundInfo(data,p.id).used} / ${p.rounds}</div><div class="caption">Según revisiones solicitadas</div></div><div class="card card-pad"><span class="stat-label">Comentarios abiertos</span><div class="numeric">${comments.filter(x=>!x.resolved).length}</div><div class="caption">En la versión seleccionada</div></div></div>
 <div class="version-strip" role="group" aria-label="Seleccionar versión">${versions.map(x=>`<button class="version-chip ${x.id===v.id?'active':''}" data-version="${x.id}">V${x.number} · ${e(x.label)} · ${e(decisionLabel(x))}</button>`).join('')}</div>
 <div class="preview-grid"><section class="preview-panel"><div class="preview-toolbar"><span>${icon('file',15)} ${e(v.filename)}</span><span>${isPdf?'PDF':'Vista previa'} · ${e(decisionLabel(v))}</span></div>
 <div class="preview-stage ${isAnnotatable?'annotatable':''}" id="preview-stage" title="${isAnnotatable?'Haz clic para agregar una anotación':'PDF: comentarios en panel lateral'}">${stageSource?(isPdf?`<iframe title="Vista del archivo PDF" src="${e(stageSource)}#toolbar=0"></iframe>`:`<img src="${e(stageSource)}" alt="Vista previa de ${e(v.filename)}" />`):`<div style="text-align:center;padding:25px">${icon('file',35)}<p class="caption">Cargando archivo local…</p></div>`}
 ${isAnnotatable?comments.filter(x=>Number.isFinite(x.x)&&Number.isFinite(x.y)).map((x,i)=>`<button class="pin ${x.resolved?'resolved':''}" style="left:${x.x}%;top:${x.y}%" data-comment="${x.id}" title="${e(x.text)}" aria-label="Anotación ${i+1}">${i+1}</button>`).join(''):''}${ui.pinDraft&&isAnnotatable?`<span class="pin draft" style="left:${ui.pinDraft.x}%;top:${ui.pinDraft.y}%">+</span>`:''}</div>
 <div class="action-row" style="margin-top:13px"><button class="btn btn-white btn-sm" data-action="download" data-id="${v.id}">${icon('download',15)} Descargar archivo</button>${isAnnotatable?'<span class="caption">Haz clic sobre la imagen para fijar un comentario.</span>':'<span class="caption">Para PDF, usa «Comentario general».</span>'}</div></section>
 <aside class="card card-pad"><div class="section-head"><div><h2 class="section-title">Comentarios y revisión</h2><p class="card-subtitle">Asociados solo a esta versión</p></div><button class="btn btn-soft btn-sm" data-action="comment-general">${icon('plus',14)} Comentario</button></div><div class="scroll-panel">${comments.length?comments.map((x,i)=>`<article class="comment-item ${ui.highlight===x.id?'highlighted':''}" id="comment-${e(x.id)}"><div class="comment-head"><span class="small-avatar" style="background:${x.role==='client'?'#ffe4cd':'#e8e5ff'}">${e(x.author.split(' ').map(t=>t[0]).slice(0,2).join(''))}</span><div style="flex:1"><strong>${e(x.author)}</strong><div class="caption">${formatDate(x.createdAt)} · ${x.role==='client'?'Cliente':'Creativo'}</div></div>${x.resolved?'<span class="pill green">Resuelto</span>':'<span class="pill amber">Abierto</span>'}</div><p>${e(x.text)}</p>${!x.resolved&&ui.role!=='client'?btn(icon('check',13)+' Resolver','resolve-comment','btn-white btn-sm',`data-id="${x.id}"`):''}</article>`).join(''):blank('Sin comentarios','Agrega una anotación o comentario general.')}</div><hr class="short-hr">${canDecide?`<div class="stack">${btn(icon('check')+' Aprobar versión','approve-version','btn-primary')}${btn(icon('edit')+' Solicitar cambios','request-changes','btn-white')}</div>`:ui.role==='client'?'<div class="note">Las decisiones solo se permiten sobre la última versión pendiente de revisión.</div>':canUpload(p,ui.role)?`<div class="stack">${btn(icon('upload')+' Cargar nueva versión','upload-version','btn-primary')}<p class="caption">El cliente podrá aprobar o solicitar cambios sobre la última versión cargada.</p></div>`:'<div class="note">Esta revisión es histórica o ya fue finalizada.</div>'}</aside></div>
 ${roundInfo(data,p.id).overLimit?'<div class="note warn mt">Se alcanzó el número de rondas incluidas. Nuevos cambios pueden requerir una ampliación acordada; esta demo nunca factura automáticamente.</div>':''}`;}
function deliveryDetail(p){const v=latestVersion(data,p.id);const isDone=p.status==='delivered';const canMark=canDeliver(p,ui.role);return `<div class="grid grid-3"><section class="card card-pad span-2"><div class="section-head"><div><h2 class="section-title">Cierre y entrega final</h2><p class="card-subtitle">El archivo que recibió aprobación</p></div>${status(p)}</div>${v?`<div class="mini-pretty"><span class="doc-icon">${icon('file',21)}</span><div style="flex:1;min-width:0"><strong class="file-label">${e(v.filename)}</strong><div class="caption">Versión ${v.number} · ${e(v.kind)} · ${formatDate(v.createdAt)}</div></div>${isDone?btn(icon('download')+' Descargar','download','btn-primary btn-sm',`data-id="${v.id}"`):''}</div>`:'<div class="note">No hay ningún archivo cargado.</div>'}<div class="mt">${isDone?'<div class="note success">Entrega registrada. La descarga corresponde al archivo local o ejemplo de este navegador.</div>':p.status==='approved'?'<div class="note success">La versión final fue aprobada. Falta registrar la entrega.</div>':`<div class="note warn">Para cerrar una entrega, el cliente debe aprobar la última versión.</div>`}</div>${canMark?`<div class="action-row mt">${btn(icon('check')+' Registrar entrega final','deliver','btn-primary')}</div>`:''}</section><aside class="card card-pad"><h2 class="section-title">Resumen</h2><dl><div class="kv"><dt>Cliente</dt><dd>${e(clientOf(data,p)?.name)}</dd></div><div class="kv"><dt>Versión</dt><dd>${v?'V'+v.number:'Sin versión'}</dd></div><div class="kv"><dt>Aprobación</dt><dd>${v?.decision==='approved'?'Aprobado':p.status==='delivered'?'Aprobado':'Pendiente'}</dd></div><div class="kv"><dt>Entrega</dt><dd>${formatDate(p.deliveredAt)}</dd></div></dl><button class="btn btn-white btn-sm" data-action="download-agreement">${icon('download',14)} Descargar acuerdo (TXT)</button></aside></div>`;}
function modal(title,form,body,submit='Guardar',note=''){
  ui.modal=form;
  root.innerHTML=`<div class="modal-overlay" id="modal-overlay"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><div class="eyebrow">TrazoDesk · Demo</div><h2 id="modal-title">${e(title)}</h2></div><button class="icon-btn" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button></div><form id="modal-form" data-form="${e(form)}"><div class="modal-body">${body}${note?`<div class="note mt">${note}</div>`:''}</div><div class="modal-foot"><button type="button" class="btn btn-white" data-action="close-modal">Cancelar</button><button type="submit" class="btn btn-primary">${e(submit)}</button></div></form></div></div>`;
  root.querySelector('input:not([type="hidden"]),textarea,select')?.focus();
}
function closeModal(){root.innerHTML='';ui.modal=null;ui.pinDraft=null;}
function field(label,name,type='text',value='',attrs=''){return `<div class="field"><label for="f-${name}">${e(label)}</label><input id="f-${name}" name="${name}" type="${type}" value="${e(value)}" ${attrs}></div>`;}
function textArea(label,name,value='',attrs=''){return `<div class="field full"><label for="f-${name}">${e(label)}</label><textarea id="f-${name}" name="${name}" ${attrs}>${e(value)}</textarea></div>`;}
function selectField(label,name,options,value=''){return `<div class="field"><label for="f-${name}">${e(label)}</label><select id="f-${name}" name="${name}">${options.map(o=>`<option value="${e(o.value)}" ${o.value===value?'selected':''}>${e(o.label)}</option>`).join('')}</select></div>`;}
function openNewProject(){if(ui.role==='client')return toast('Los clientes pueden crear solicitudes, no proyectos.','error');const opts=data.clients.map(c=>({value:c.id,label:c.name}));modal('Nuevo proyecto','new-project',`<div class="formgrid">${field('Nombre del proyecto','name','text','','required maxlength="100"')}${selectField('Cliente','clientId',opts)}${field('Servicio creativo','service','text','Diseño gráfico','required maxlength="80"')}${field('Fecha objetivo','deadline','date',new Date(Date.now()+14*864e5).toISOString().slice(0,10),'required')}${field('Importe referencial (USD)','budget','number','300','required min="0" max="1000000" step="1"')}${field('Rondas incluidas','rounds','number','2','required min="0" max="25"')}${textArea('Alcance incluido','scope','','required minlength="5" maxlength="2000"')}${textArea('Exclusiones / fuera de alcance','exclusions','','maxlength="1500"')}${ui.role==='agency'?selectField('Responsable','ownerId',data.team.map(m=>({value:m.id,label:m.name}))):'<input name="ownerId" type="hidden" value="m1">'}</div>`,'Crear acuerdo pendiente','Este proyecto no empezará hasta que el cliente acepte sus condiciones.');}
function openNewRequest(){const opts=data.clients.map(c=>({value:c.id,label:c.name}));modal('Nueva solicitud','new-request',`<div class="formgrid">${ui.role==='client'?`<input type="hidden" name="clientId" value="${e(ui.clientId)}"><div class="field full"><label>Cliente</label><div class="note">${e(data.clients.find(c=>c.id===ui.clientId)?.name)}</div></div>`:selectField('Cliente','clientId',opts)}${field('Título del encargo','title','text','','required maxlength="100"')}${field('Tipo de servicio','service','text','Diseño gráfico','required maxlength="80"')}${field('Presupuesto orientativo (USD)','budget','number','250','required min="0" max="1000000"')}${field('Fecha estimada','deadline','date',new Date(Date.now()+21*864e5).toISOString().slice(0,10),'required')}${textArea('Descripción del encargo','details','','required minlength="5" maxlength="2000"')}</div>`,'Enviar solicitud','Enviar aquí solo registra una solicitud local; no se notifica a un profesional real.');}
function openUpload(){const p=projectById(ui.projectId);if(!canUpload(p,ui.role))return toast('No puedes subir versiones en este estado.','error');modal('Subir versión para revisión','upload-version',`<div class="formgrid">${field('Nombre de la versión','label','text',versionsOf(data,p.id).length?'Propuesta actualizada':'Primera propuesta','required maxlength="90"')}<div class="field full"><label for="fileupload">Archivo JPG, PNG o PDF (máx. 12 MB)</label><div class="filebox">${icon('upload',26)}<input id="fileupload" name="file" type="file" accept=".jpg,.jpeg,.png,.pdf,image/png,image/jpeg,application/pdf" required></div></div></div>`,'Guardar y enviar a revisión','El archivo se guarda solo en IndexedDB, dentro de este navegador. No existe almacenamiento en la nube.');}
function openComment(x=null,y=null){const p=projectById(ui.projectId),v=data.versions.find(v=>v.id===ui.versionId),last=latestVersion(data,p?.id);
 if(!p||!v||v.id!==last?.id||p.status!=='in_review'||v.decision!=='pending')return toast('Los comentarios nuevos solo se agregan a la versión actual pendiente.','error');
 if(v.kind==='application/pdf'&&x!==null)return toast('En PDF se admite comentario general, no posición visual.','error');
 ui.pinDraft=(x!==null&&y!==null)?{x,y}:null;modal(x!==null?'Nueva anotación visual':'Comentario de revisión','comment',`<input type="hidden" name="versionId" value="${e(v.id)}"><input type="hidden" name="x" value="${x??''}"><input type="hidden" name="y" value="${y??''}"><div class="field"><label for="f-comment">Comentario</label><textarea id="f-comment" name="comment" required minlength="2" maxlength="1500" placeholder="Describe un ajuste concreto o deja una observación…"></textarea></div>`,'Agregar comentario',x!==null?'La anotación quedará vinculada a esta versión y posición de la imagen.':'El comentario se guardará en esta versión, sin marcador de posición.');}
function openChangeModal(){const p=projectById(ui.projectId),v=latestVersion(data,p?.id);if(!canReview(p,v,ui.role))return toast('La última versión no permite una nueva decisión.','error');const round=roundInfo(data,p.id);modal('Solicitar correcciones','request-changes',`${textArea('Describe los cambios necesarios','reason','','required minlength="5" maxlength="1500"')}`, 'Solicitar cambios',round.overLimit?'Se agotaron las rondas incluidas. Una ronda adicional no genera cobro automático; requiere acuerdo si altera las condiciones.':'La solicitud quedará registrada en el historial y contará como una ronda de revisión.');}
function openExtra(){if(ui.role==='client')return toast('La propuesta de extras corresponde al equipo creativo.','error');const projects=currentProjects().filter(p=>p.agreementAcceptedAt);if(!projects.length)return toast('Necesitas un proyecto con acuerdo aceptado.','error');modal('Proponer ampliación de alcance','new-extra',`<div class="formgrid">${selectField('Proyecto','projectId',projects.map(p=>({value:p.id,label:p.name})),ui.projectId&&projects.some(p=>p.id===ui.projectId)?ui.projectId:projects[0].id)}${field('Importe adicional (USD)','amount','number','60','required min="0" max="1000000" step="1"')}${textArea('Trabajo adicional solicitado','title','','required minlength="5" maxlength="500"')}</div>`,'Enviar propuesta','El cliente podrá aceptar o rechazar este extra. No se emiten cobros ni facturas.');}
function openAssign(id){if(ui.role!=='agency')return toast('Solo la agencia puede reasignar proyectos.','error');const p=projectById(id);if(!p)return;modal('Reasignar proyecto','assign',`<input type="hidden" name="projectId" value="${e(p.id)}">${selectField('Responsable','ownerId',data.team.map(m=>({value:m.id,label:m.name})),p.ownerId)}`,'Guardar asignación');}
function canDo(id){return projectById(id);}
function createProject(fields){const p={id:uid('p'),name:String(fields.name).trim(),clientId:fields.clientId,ownerId:fields.ownerId||'m1',service:String(fields.service).trim(),status:'agreement',deadline:fields.deadline,createdAt:new Date().toISOString(),budget:Number(fields.budget),currency:'USD',scope:String(fields.scope).trim(),exclusions:String(fields.exclusions||'').trim(),rounds:Number(fields.rounds),agreementAcceptedAt:null,deliveredAt:null};data.projects.unshift(p);eventRecord(p.id,'Proyecto creado; acuerdo pendiente de aceptación.','agreement');persist();closeModal();openProject(p.id,'agreement');toast('Proyecto creado con acuerdo pendiente.');}
async function formHandler(event){event.preventDefault();const form=event.target.closest('form[data-form]');if(!form)return;const values=Object.fromEntries(new FormData(form).entries());const type=form.dataset.form;
 try{
 if(type==='new-request'){
   if(ui.role==='client'&&values.clientId!==ui.clientId)throw new Error('Cliente no válido.');
   if(!data.clients.some(c=>c.id===values.clientId))throw new Error('Selecciona un cliente.');
   data.requests.unshift({id:uid('r'),clientId:values.clientId,title:values.title.trim(),details:values.details.trim(),service:values.service.trim(),budget:Number(values.budget),deadline:values.deadline,status:'pending',createdAt:new Date().toISOString()});eventRecord(null,'Nueva solicitud creada.','request');persist();closeModal();viewTo('requests');toast('Solicitud registrada en la demo.');
 }else if(type==='new-project'){
   if(ui.role==='client')throw new Error('Los clientes no pueden crear proyectos.');
   if(!data.clients.some(c=>c.id===values.clientId))throw new Error('Cliente inexistente.');
   if(!data.team.some(t=>t.id===values.ownerId))throw new Error('Responsable inexistente.');
   createProject(values);
 }else if(type==='upload-version'){
   const p=projectById(ui.projectId);if(!canUpload(p,ui.role))throw new Error('No puedes subir una versión en este estado.');const file=values.file;
   if(!allowedFile(file))throw new Error('Elige un archivo PNG, JPG o PDF de 12 MB como máximo.');
   const older=versionsOf(data,p.id),id=uid('v');
   await saveFile(id,file);
   older.filter(v=>v.decision==='pending').forEach(v=>v.decision='superseded');
   const v={id,projectId:p.id,number:(older[0]?.number||0)+1,label:values.label.trim(),filename:file.name,kind:file.type,sample:null,round:roundInfo(data,p.id).used+1,createdAt:new Date().toISOString(),decision:'pending'};
   data.versions.push(v);p.status='in_review';eventRecord(p.id,`Nueva versión V${v.number} enviada para revisión.`,'review');persist();closeModal();ui.view='detail';ui.tab='review';ui.versionId=id;clearPreview();render();await loadPreview(v);toast('Versión guardada localmente y enviada a revisión.');
 }else if(type==='comment'){
   const p=projectById(ui.projectId),v=data.versions.find(v=>v.id===values.versionId);if(!p||!v||v.id!==latestVersion(data,p.id)?.id||p.status!=='in_review'||v.decision!=='pending')throw new Error('Versión no disponible para comentar.');
   const x=values.x===''?null:Math.max(0,Math.min(100,Number(values.x))),y=values.y===''?null:Math.max(0,Math.min(100,Number(values.y)));
   if(v.kind==='application/pdf'&&(x!==null||y!==null))throw new Error('Las posiciones en PDF no están habilitadas.');
   data.comments.push({id:uid('cm'),versionId:v.id,author:actor(),role:ui.role,text:String(values.comment).trim(),x,y,createdAt:new Date().toISOString(),resolved:false});eventRecord(p.id,`${actor()} agregó un comentario a V${v.number}.`,'comment');persist();closeModal();render();toast('Comentario agregado.');
 }else if(type==='request-changes'){
   const p=projectById(ui.projectId),v=latestVersion(data,p?.id);if(!canReview(p,v,ui.role))throw new Error('No se pueden solicitar cambios en este estado.');
   v.decision='changes_requested';p.status='changes_requested';data.comments.push({id:uid('cm'),versionId:v.id,author:actor(),role:'client',text:String(values.reason).trim(),x:null,y:null,createdAt:new Date().toISOString(),resolved:false});eventRecord(p.id,`Cliente solicitó cambios en V${v.number}.`,'review');persist();closeModal();render();toast('Cambios solicitados. La revisión quedó registrada.');
 }else if(type==='new-extra'){
   const p=projectById(values.projectId);if(ui.role==='client'||!p?.agreementAcceptedAt)throw new Error('Proyecto no válido para extras.');
   data.extras.unshift({id:uid('ex'),projectId:p.id,title:String(values.title).trim(),amount:Number(values.amount),status:'pending',createdAt:new Date().toISOString()});eventRecord(p.id,'Ampliación de alcance propuesta para aceptación del cliente.','agreement');persist();closeModal();ui.view='finance';ui.filter='all';render();toast('Extra propuesto. Falta aceptación del cliente.');
 }else if(type==='assign'){
   const p=projectById(values.projectId);if(ui.role!=='agency'||!p||!data.team.some(m=>m.id===values.ownerId))throw new Error('Asignación inválida.');p.ownerId=values.ownerId;eventRecord(p.id,`Proyecto asignado a ${data.team.find(m=>m.id===values.ownerId).name}.`,'history');persist();closeModal();render();toast('Responsable actualizado.');
 }
 }catch(err){toast(err?.message||'No se pudo completar la acción.','error');console.error(err);}
}
function clearPreview(){if(previewUrl){URL.revokeObjectURL(previewUrl);previewUrl=null;}}
async function loadPreview(v){if(!v||v.sample)return;const expected=v.id;const f=await readFile(v.id);if(ui.versionId!==expected||ui.view!=='detail'||ui.tab!=='review')return;clearPreview();if(f){previewUrl=URL.createObjectURL(f);render();}else{toast('Este archivo no está disponible en el navegador actual.','error');}}
async function downloadVersion(id){const v=data.versions.find(x=>x.id===id),p=v&&projectById(v.projectId);if(!v||!p)return toast('No puedes descargar este archivo.','error');if(p.status==='delivered'||p.status==='approved'||ui.role!=='client'||v.decision==='pending'||v.decision==='changes_requested'){
 const link=document.createElement('a');link.download=v.filename;
 if(v.sample){link.href=new URL(v.sample,document.baseURI).href;}else{const blob=await readFile(v.id);if(!blob)return toast('Archivo local no encontrado.','error');link.href=URL.createObjectURL(blob);}
 document.body.append(link);link.click();link.remove();if(!v.sample)setTimeout(()=>URL.revokeObjectURL(link.href),5000);toast('Descarga iniciada.');
 }else{toast('Esta entrega aún no está disponible para descarga.','error');}}
function downloadBlob(dataString,name,type='text/plain;charset=utf-8'){const blob=new Blob([dataString],{type});const link=document.createElement('a');link.download=name;link.href=URL.createObjectURL(blob);document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(link.href),5000);}
function downloadAgreement(p){const c=clientOf(data,p);downloadBlob(`TRAZODESK — ACUERDO DE DEMOSTRACIÓN\nProyecto: ${p.name}\nCliente: ${c?.name||'—'}\nServicio: ${p.service}\nFecha objetivo: ${p.deadline}\nImporte referencial: ${formatMoney(p.budget)}\nRondas incluidas: ${p.rounds}\n\nALCANCE:\n${p.scope}\n\nEXCLUSIONES:\n${p.exclusions||'No detalladas'}\n\nACEPTACIÓN EN DEMO: ${p.agreementAcceptedAt||'Pendiente'}\n\nDocumento de ejemplo, sin validez contractual y sin servicios comerciales activos.\n`,`acuerdo-${p.id}.txt`);}
function changeRole(role){if(!validRoles.includes(role))return;ui.role=role;clearPreview();ui.view='dashboard';ui.projectId=null;ui.versionId=null;ui.mobileNav=false;ui.filter='all';ui.search='';render();toast(`Perspectiva: ${ROLES[role].label}. Permisos simulados.`);}
async function clickHandler(ev){const target=ev.target;
 const nav=target.closest('[data-nav]');if(nav){clearPreview();viewTo(nav.dataset.nav);return;}
 const open=target.closest('[data-open-project]');if(open){clearPreview();openProject(open.dataset.openProject,open.dataset.openTab||'overview');if(ui.tab==='review')await loadPreview(data.versions.find(v=>v.id===ui.versionId));return;}
 const tab=target.closest('[data-tab]');if(tab){const old=ui.tab;ui.tab=tab.dataset.tab;ui.pinDraft=null;if(old==='review')clearPreview();render();if(ui.tab==='review')await loadPreview(data.versions.find(v=>v.id===ui.versionId));return;}
 const filt=target.closest('[data-filter]');if(filt){ui.filter=filt.dataset.filter;render();return;}
 const ver=target.closest('[data-version]');if(ver){ui.versionId=ver.dataset.version;ui.pinDraft=null;ui.highlight=null;clearPreview();render();await loadPreview(data.versions.find(v=>v.id===ui.versionId));return;}
 const comment=target.closest('[data-comment]');if(comment){ui.highlight=comment.dataset.comment;render();document.getElementById('comment-'+ui.highlight)?.scrollIntoView({block:'nearest',behavior:'smooth'});return;}
 const clickStage=target.closest('#preview-stage');if(clickStage){const p=projectById(ui.projectId),v=data.versions.find(x=>x.id===ui.versionId),l=latestVersion(data,p?.id);if(!p||!v||v.kind==='application/pdf'||v.id!==l?.id||p.status!=='in_review'||v.decision!=='pending')return;const rect=clickStage.getBoundingClientRect();const x=Math.max(2,Math.min(98,Math.round((ev.clientX-rect.left)/rect.width*1000)/10));const y=Math.max(2,Math.min(98,Math.round((ev.clientY-rect.top)/rect.height*1000)/10));openComment(x,y);return;}
 const b=target.closest('[data-action]');if(!b)return;
 const a=b.dataset.action,id=b.dataset.id;
 try{
 if(a==='close-modal'){closeModal();return;}if(a==='mobile-open'){ui.mobileNav=true;render();return;}if(a==='mobile-close'){ui.mobileNav=false;render();return;}
 if(a==='new-project'){openNewProject();return;}if(a==='new-request'){openNewRequest();return;}if(a==='upload-version'){openUpload();return;}if(a==='new-extra'){openExtra();return;}if(a==='comment-general'){openComment();return;}if(a==='request-changes'){openChangeModal();return;}
 if(a==='tab-review'){ui.tab='review';render();await loadPreview(data.versions.find(v=>v.id===ui.versionId));return;}if(a==='tab-agreement'){ui.tab='agreement';render();return;}
 if(a==='view-agreement'){openProject(id,'agreement');return;}if(a==='view-delivery'){openProject(id,'delivery');return;}if(a==='goto-reviews'){viewTo('reviews');return;}if(a==='goto-projects'){viewTo('projects');return;}
 if(a==='accept-request'){
   const r=data.requests.find(x=>x.id===id);if(ui.role==='client'||!r||r.status!=='pending')throw new Error('No puedes convertir esta solicitud.');
   r.status='accepted';createProject({name:r.title,clientId:r.clientId,ownerId:'m1',service:r.service,deadline:r.deadline,budget:r.budget,rounds:2,scope:r.details,exclusions:'Fuera del alcance descrito en la solicitud.'});return;
 }
 if(a==='reject-request'){const r=data.requests.find(x=>x.id===id);if(ui.role==='client'||!r||r.status!=='pending')throw new Error('No puedes descartar esta solicitud.');if(!confirm('¿Descartar esta solicitud de ejemplo?'))return;r.status='rejected';eventRecord(null,`Solicitud descartada: ${r.title}.`,'request');persist();render();toast('Solicitud descartada.');return;}
 if(a==='accept-agreement'){const p=projectById(ui.projectId);if(!canAcceptAgreement(p,ui.role))throw new Error('Solo el cliente puede aceptar el acuerdo pendiente.');p.agreementAcceptedAt=new Date().toISOString();p.status='active';eventRecord(p.id,'Acuerdo aceptado por el cliente.','agreement');persist();render();toast('Acuerdo aceptado. El proyecto está en producción.');return;}
 if(a==='approve-version'){const p=projectById(ui.projectId),v=latestVersion(data,p?.id);if(!canReview(p,v,ui.role))throw new Error('No se puede aprobar esta versión.');v.decision='approved';p.status='approved';eventRecord(p.id,`Versión V${v.number} aprobada por el cliente.`,'approval');persist();render();toast('Versión aprobada. Falta registrar la entrega.');return;}
 if(a==='deliver') {const p=projectById(id||ui.projectId),v=latestVersion(data,p?.id);if(!canDeliver(p,ui.role)||v?.decision!=='approved')throw new Error('La última versión debe estar aprobada antes de entregar.');p.status='delivered';p.deliveredAt=new Date().toISOString();eventRecord(p.id,`Entrega registrada: ${v.filename}.`,'delivery');persist();render();toast('Entrega registrada correctamente.');return;}
 if(a==='resolve-comment'){const cm=data.comments.find(x=>x.id===id),v=cm&&data.versions.find(v=>v.id===cm.versionId),p=v&&projectById(v.projectId);if(ui.role==='client'||!p||!v||cm.resolved)throw new Error('No puedes resolver este comentario.');cm.resolved=true;eventRecord(p.id,'Comentario marcado como resuelto.','comment');persist();render();toast('Comentario resuelto.');return;}
 if(a==='accept-extra'||a==='reject-extra'){const x=data.extras.find(x=>x.id===id),p=x&&projectById(x.projectId);if(!x||!p||!canDecideExtra(x,ui.role))throw new Error('El extra no puede modificarse.');x.status=a==='accept-extra'?'accepted':'rejected';eventRecord(p.id,`Ampliación de alcance ${x.status==='accepted'?'aceptada':'rechazada'}: ${x.title}.`,'agreement');persist();render();toast('Decisión registrada.');return;}
 if(a==='assign'){openAssign(id);return;}
 if(a==='download'){await downloadVersion(id);return;}
 if(a==='download-agreement'){const p=projectById(ui.projectId);if(!p)throw new Error('No se encontró el proyecto.');downloadAgreement(p);return;}
 if(a==='export-json'){downloadBlob(JSON.stringify(data,null,2),'trazodesk-demo-datos.json','application/json;charset=utf-8');toast('Datos de demostración exportados.');return;}
 if(a==='copy-client-demo-link'){
   const p=projectById(ui.projectId);if(!p)throw new Error('Proyecto no encontrado.');const url=new URL(location.href);url.searchParams.set('role','client');url.searchParams.set('client',p.clientId);url.searchParams.set('project',p.id);await navigator.clipboard.writeText(url.href);toast('Enlace de simulación copiado. NO es privado ni seguro.');return;
 }
 if(a==='reset'){
   if(!confirm('¿Reiniciar todos los datos y archivos de esta demo en este navegador?'))return;
   await resetFiles();resetState();data=seedState();ui.view='dashboard';ui.projectId=null;ui.tab='overview';ui.versionId=null;ui.search='';ui.filter='all';clearPreview();render();toast('Demo reiniciada con datos de ejemplo.');return;
 }
 }catch(err){toast(err?.message||'Ocurrió un error.','error');console.error(err);}
}
app.addEventListener('click',clickHandler);
root.addEventListener('click',ev=>{if(ev.target.id==='modal-overlay')closeModal();else if(ev.target.closest('[data-action="close-modal"]'))closeModal();});
root.addEventListener('submit',formHandler);
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&ui.modal)closeModal();});
app.addEventListener('change',async ev=>{
 if(ev.target.id==='role-switch'){changeRole(ev.target.value);return;}
 if(ev.target.id==='client-switch'&&ui.role==='client'){
   if(!data.clients.some(c=>c.id===ev.target.value))return;ui.clientId=ev.target.value;clearPreview();ui.view='dashboard';ui.projectId=null;ui.versionId=null;ui.filter='all';render();return;
 }
});
app.addEventListener('input',ev=>{if(ev.target.id==='project-search'){const position=ev.target.selectionStart;ui.search=ev.target.value;render();const input=document.getElementById('project-search');input?.focus();input?.setSelectionRange(position,position);}});
if(params.get('project')&&projectById(params.get('project'))){ui.view='detail';ui.projectId=params.get('project');ui.tab='overview';ui.versionId=latestVersion(data,ui.projectId)?.id||null;}
render();
